fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(2, 0);
        host::display::state_set(3, 1);
        host::display::state_set(4, 2);
        host::display::state_set(5, 3);
        host::display::state_set(6, 30);
        host::display::state_set(7, 80);
        host::display::state_set(8, 130);
        host::display::state_set(9, 0);
        host::display::state_set(10, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(11) == 0;
    host::display::state_set(11, down);
    let score: i32 = host::display::state_get(9);
    if host::display::state_get(10) == 1 {
        host::display::clear(0x140008);
        host::display::draw_string(130, 180, "THEY LANDED", 0xff4040, 4);
        host::display::draw_string(150, 250, "KILLS", 0x808080, 2);
        host::display::draw_number(260, 244, score, 0xffffff, 3);
        host::display::draw_string(130, 320, "TAP TO DEFEND AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut px: i32 = host::display::pointer_x() - 20;
        if px < 0 { px = 0; }
        if px > w - 40 { px = w - 40; }
        let mut blx: i32 = host::display::state_get(1);
        let mut bly: i32 = host::display::state_get(2);
        if tap && bly == 0 {
            blx = px + 18;
            bly = h - 40;
        }
        if bly > 0 {
            bly = bly - 9;
            if bly < 4 { bly = 0; }
        }
        let mut spd: i32 = 1 + score / 5;
        if spd > 4 { spd = 4; }
        host::display::clear(0x000010);
        let mut i: i32 = 0;
        while i < 3 {
            let rnd: i32 = host::display::state_get(3 + i);
            let ix: i32 = hash(rnd * 13 + i) % (w - 32);
            let mut iy: i32 = host::display::state_get(6 + i);
            iy = iy + spd;
            if bly > 0 && blx >= ix && blx < ix + 28 && bly >= iy && bly < iy + 20 {
                host::display::state_set(9, host::display::state_get(9) + 1);
                host::display::state_set(3 + i, rnd + 1);
                iy = 20;
                bly = 0;
            }
            if iy > h - 40 {
                host::display::state_set(10, 1);
            }
            host::display::state_set(6 + i, iy);
            host::display::fill_rect(ix, iy, 28, 20, 0xdd44dd);
            host::display::fill_rect(ix + 4, iy + 6, 6, 6, 0x000000);
            host::display::fill_rect(ix + 18, iy + 6, 6, 6, 0x000000);
            i = i + 1;
        }
        host::display::state_set(1, blx);
        host::display::state_set(2, bly);
        if bly > 0 {
            host::display::fill_rect(blx - 2, bly, 4, 10, 0xffffff);
        }
        host::display::fill_rect(px, h - 24, 40, 12, 0x00ddff);
        host::display::fill_triangle(px + 12, h - 24, px + 28, h - 24, px + 20, h - 36, 0x00ddff);
        host::display::draw_number(8, 6, score, 0xffffff, 2);
    }
    host::display::present();
}
